        if f > max_cutoff:
            break
        if g > best_g.get((gx, gy, gz), float('inf')):
            continue

        if (gx, gy, gz) in q_candidates:
            total = g + q_candidates[(gx, gy, gz)]
            if total < best_dist:
                best_dist = total
                max_cutoff = min(max_cutoff, best_dist)

