# Neighbor step vectors (26 directions)
STEPS = []
for dx in [-1, 0, 1]:
    for dy in [-1, 0, 1]:
        for dz in [-1, 0, 1]:
            if dx == 0 and dy == 0 and dz == 0:
                continue
            cost = math.sqrt(dx*dx + dy*dy + dz*dz)
            STEPS.append((dx, dy, dz, cost))

def get_pdb_res_idx(prot, pos):
    if prot == 'XLMBQL':
        if 84 <= pos <= 175:
            return pos - 83
        elif 189 <= pos <= 381:
            return pos - 96
        else:
            return None
    elif prot == 'XLCQ5E':
        if 87 <= pos <= 235:
            return pos - 86
        elif 243 <= pos <= 346:
            return pos - 93
        else:
            return None
    return None

def get_candidates(pt, blocked, min_c):
    nx, ny, nz = blocked.shape
    px, py, pz = pt
    cand = {}
    for x in range(int(math.floor(px - 7.0)), int(math.ceil(px + 7.0)) + 1):
        gx = x - min_c[0]
        if gx < 0 or gx >= nx:
            continue
        for y in range(int(math.floor(py - 7.0)), int(math.ceil(py + 7.0)) + 1):
            gy = y - min_c[1]
            if gy < 0 or gy >= ny:
                continue
            for z in range(int(math.floor(pz - 7.0)), int(math.ceil(pz + 7.0)) + 1):
                gz = z - min_c[2]
                if gz < 0 or gz >= nz:
                    continue
                if not blocked[gx, gy, gz]:
                    d = math.sqrt((x - px)**2 + (y - py)**2 + (z - pz)**2)
                    if d <= 7.0:
                        cand[(gx, gy, gz)] = d
    return cand

def compute_surface_distance(P, Q, blocked, min_c, max_cutoff=34.0):
