        wx = gx + min_c[0]
        wy = gy + min_c[1]
        wz = gz + min_c[2]
        h = math.sqrt((wx - qx)**2 + (wy - qy)**2 + (wz - qz)**2)
        f = d + h
        if f <= max_cutoff:
            best_g[(gx, gy, gz)] = d
            heapq.heappush(pq, (f, d, gx, gy, gz))

    if best_dist <= max_cutoff:
